class Solution {
public:
    double maxAverageRatio(vector<vector<int>>& classes, int extraStudents) {
        struct Cmp {
            bool operator()(const pair<int,int>& a, const pair<int,int>& b) const {
                double ga = (double)(a.first + 1) / (a.second + 1) - (double)a.first / a.second;
                double gb = (double)(b.first + 1) / (b.second + 1) - (double)b.first / b.second;
                return ga < gb;
            }
        };
        priority_queue<pair<int,int>, vector<pair<int,int>>, Cmp> pq;
        for (auto& c : classes) {
            pq.push({c[0], c[1]});
        }
        for (int i = 0; i < extraStudents; i++) {
            auto [p, t] = pq.top();
            pq.pop();
            pq.push({p + 1, t + 1});
        }
        double sum = 0;
        int n = classes.size();
        while (!pq.empty()) {
            auto [p, t] = pq.top();
            pq.pop();
            sum += (double)p / t;
        }
        return sum / n;
    }
};
